import java.io.BufferedInputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        long[] order = new long[n];
        for (int i = 0; i < n; i++) {
            int height = fs.nextInt();
            order[i] = ((long) height << 32) | i;
        }

        Arrays.sort(order);

        boolean[] active = new boolean[n];
        int components = 0;
        int maxComponents = 0;

        for (int end = n - 1; end >= 0; ) {
            long height = order[end] >>> 32;
            int start = end;

            while (start >= 0 && (order[start] >>> 32) == height) {
                int index = (int) order[start];
                active[index] = true;
                components++;

                if (index > 0 && active[index - 1]) components--;
                if (index + 1 < n && active[index + 1]) components--;

                start--;
            }

            maxComponents = Math.max(maxComponents, components);
            end = start;
        }

        System.out.println(maxComponents + 1);
    }
}
